import { test } from '@playwright/test'
import { loginWithRealAccount, waitForPageLoading } from '../fixtures/auth-helpers.js'
import fs from 'fs'

const OUT = 'D:/out/real'

test.describe.serial('capture real pages 1:1', () => {
  test.setTimeout(240000)

  test.beforeAll(() => {
    if (!fs.existsSync(OUT)) fs.mkdirSync(OUT, { recursive: true })
  })

  test('capture 4 pages', async ({ page }) => {
    await loginWithRealAccount(page)
    await page.waitForLoadState('networkidle').catch(() => {})

    // 1. 预售合同签订列表
    await page.goto('/#/xsht/contractMainInfo/contractMainInfo/pre', { waitUntil: 'domcontentloaded' })
    await page.waitForTimeout(4000)
    await waitForPageLoading(page).catch(() => {})
    await page.waitForTimeout(1500)
    await page.screenshot({ path: `${OUT}/real_p1.png`, fullPage: false })
    console.log('P1 url:', page.url())

    // 2. 项目备案申请详情: find a project id via API
    const projectId = await page.evaluate(async () => {
      const token = sessionStorage.getItem('Admin-Token')
      const res = await fetch('/api/v3.0/building/project/page?pageNum=1&pageSize=1', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: 'Bearer ' + token } : {}) },
        body: JSON.stringify({ pageNum: 1, pageSize: 5 })
      })
      const data = await res.json()
      const rows = data.rows || (data.data && data.data.rows) || []
      return rows.length ? (rows[0].projectId || rows[0].id) : null
    })
    console.log('projectId:', projectId)
    if (projectId) {
      await page.goto(`/#/projectmanage/customerProject/${projectId}?formMode=view&id=${projectId}`, { waitUntil: 'domcontentloaded' })
      await page.waitForTimeout(4500)
      await waitForPageLoading(page).catch(() => {})
      await page.waitForTimeout(1500)
      await page.screenshot({ path: `${OUT}/real_p2.png`, fullPage: true })
      console.log('P2 url:', page.url())

      // 3. 楼盘表 - buildingId from project
      const buildingId = await page.evaluate(async (pid) => {
        const token = sessionStorage.getItem('Admin-Token')
        const res = await fetch('/api/v3.0/building/building/list?projectId=' + pid, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: 'Bearer ' + token } : {}) },
          body: JSON.stringify({ pageNum: 1, pageSize: 10 })
        })
        const data = await res.json()
        const rows = data.rows || (data.data && data.data.rows) || (data.data && data.data.list) || []
        return rows.length ? (rows[0].buildingId || rows[0].id) : null
      }, projectId).catch(() => null)
      console.log('buildingId:', buildingId)

      if (buildingId) {
        await page.goto(`/#/projectmanage/buildingTable?id=${buildingId}&projectId=${projectId}`, { waitUntil: 'domcontentloaded' })
        await page.waitForTimeout(4500)
        await waitForPageLoading(page).catch(() => {})
        await page.waitForTimeout(1500)
        await page.screenshot({ path: `${OUT}/real_p3.png`, fullPage: true })
        console.log('P3 url:', page.url())

        // 4. 楼幢维护
        await page.goto(`/#/projectmanage/buildingInfo/${buildingId}?formMode=edit&id=${buildingId}`, { waitUntil: 'domcontentloaded' })
        await page.waitForTimeout(4500)
        await waitForPageLoading(page).catch(() => {})
        await page.waitForTimeout(1500)
        await page.screenshot({ path: `${OUT}/real_p4.png`, fullPage: true })
        console.log('P4 url:', page.url())
      }
    }
  })
})

